const cfg = $('Select Topic & Config').first().json;
const rawContent = ($input.first().json.message?.content || '{}')
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();

let parsed = {};
try {
  parsed = JSON.parse(rawContent);
} catch (e) {
  parsed = {};
}

function cleanAscii(str, fallback = '') {
  const s = String(str || fallback)
    .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE00}-\u{FE0F}]/gu, '')
    .replace(/[\u2715\u2714\u2713]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  return s || fallback;
}

const isCostcoRealStory = cfg.styleKey === 'COSTCO_REAL_REFUND_STORY' || Boolean(cfg.useRealCostcoReceipts);

const title = cleanAscii(
  parsed.title,
  isCostcoRealStory ? 'How I Got $55 Back at Costco With Keeps' : 'Stores Owe You Price Drop Refunds'
);
const heroHeadline = String(
  parsed.heroHeadline || (isCostcoRealStory ? 'I GOT $55+ BACK\nAT COSTCO!' : 'STORES OWE YOU\nPRICE-DROP CASH')
)
  .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE00}-\u{FE0F}]/gu, '')
  .trim()
  .toUpperCase()
  .replace(/\\[nN]/g, '\n');
const heroSubhead = cleanAscii(
  parsed.heroSubhead,
  'Most shoppers lose $800+/yr because they never track price drops or return windows.'
);
const hook = cleanAscii(
  isCostcoRealStory
    ? 'I just walked into Costco and got over 55 dollars refunded back to my Visa card thanks to Keeps!'
    : parsed.hook,
  'Did you know stores legally owe you cash back when prices drop after you buy?'
);
const mainContent = cleanAscii(
  isCostcoRealStory
    ? 'Here is my actual receipt proof. I bought items at Costco, snapped my receipt into the Keeps app in two seconds, and forgot about it. A few days later, Keeps sent me an email and a push alert because those items dropped in price! I walked right up to the Costco counter and got two instant Visa refunds: 43 dollars and 56 cents on the first slip, and 16 dollars and 34 cents on the second. That is nearly 60 dollars back in my pocket without returning a single item!'
    : parsed.mainContent,
  'Most shoppers lose hundreds of dollars to crumpled receipts, faded thermal ink, and expired return deadlines. With Keeps Receipt Scanner, just snap any receipt once. Our AI extracts the store, items, return deadline, and warranty in two seconds. Enable Auto Price Watch and Keeps checks prices every four hours across Best Buy, Costco, Target, Walmart, and Amazon, sending an instant push alert when prices drop so you claim your cash refund.'
);
const cta = cleanAscii(
  parsed.cta,
  'Search Keeps Receipt Scanner on the App Store and Google Play, or tap the link in bio to download free!'
);

let flatHashtags = ['#receiptscanner', '#pricematch', '#costco', '#costcofinds', '#moneytips', '#shoppinghacks', '#savingmoney', '#personalfinance', '#keepsapp'];
if (parsed.hashtags) {
  const combined = [
    ...(parsed.hashtags.pillar || []),
    ...(parsed.hashtags.platform || []),
    ...(parsed.hashtags.engagement || [])
  ].filter(Boolean);
  if (combined.length >= 4) flatHashtags = combined;
}

const numClips = 6;
const words = mainContent.split(/\s+/).filter(w => w.length > 0);
const chunkSize = Math.max(1, Math.ceil(words.length / numClips));
const segments = [];
for (let i = 0; i < numClips; i++) {
  let seg = words.slice(i * chunkSize, (i + 1) * chunkSize).join(' ').trim();
  if (seg && !/[.?!]$/.test(seg)) {
    seg = seg.replace(/[,;:]\s*$/, '') + '.';
  }
  segments.push(seg || 'Keeps AI watches your receipts 24/7.');
}

const sceneLines = [
  `${hook} ${segments[0]}`.trim(),
  segments[1],
  segments[2],
  segments[3],
  segments[4],
  `${segments[5]} ${cta}`.trim()
];

const dc = cfg.defaultCase || {};
const cs = parsed.caseStudy || {};
const caseStudy = isCostcoRealStory
  ? {
      store: 'COSTCO',
      item: 'Warehouse Price Match',
      paidPrice: '$189.90',
      newPrice: '$130.00',
      refundAmount: '$55.00+',
      returnDays: '30 DAYS',
      warrantyPeriod: '2 YEARS',
      alertHeadline: 'Keeps Email + Push Alert: Claimed $55+ Back at Costco'
    }
  : {
      store: cleanAscii(cs.store, dc.store || 'BEST BUY').toUpperCase().slice(0, 22),
      item: cleanAscii(cs.item, dc.item || 'Sony WH-1000XM5 Headphones').slice(0, 32),
      paidPrice: cleanAscii(cs.paidPrice, dc.paidPrice || '$349.99'),
      newPrice: cleanAscii(cs.newPrice, dc.newPrice || '$279.99'),
      refundAmount: cleanAscii(cs.refundAmount, dc.refundAmount || '$70.00'),
      returnDays: cleanAscii(cs.returnDays, dc.returnDays || '15 DAYS').toUpperCase(),
      warrantyPeriod: cleanAscii(cs.warrantyPeriod, dc.warrantyPeriod || '1 YEAR').toUpperCase(),
      alertHeadline: cleanAscii(cs.alertHeadline, dc.alertHeadline || '12 Days Left to Claim Refund Before Return Window Closes').slice(0, 52)
    };

const defaultPains = [
  'Missed 14-day & 30-day store return deadlines',
  'Unclaimed post-purchase price drops ($40-$150+)',
  'Thermal paper ink fades before warranty claims'
];
const rawPains = Array.isArray(parsed.painPoints) ? parsed.painPoints : [];
const painPoints = [0, 1, 2].map(i => cleanAscii(rawPains[i], defaultPains[i]).slice(0, 48));

const defaultProps = [
  '1-Tap AI Receipt & Warranty Extraction in 2s',
  '24/7 Price Watch Checks Stores Every 4 Hours',
  'Automatic Return Countdown Push Reminders',
  '1-Tap CSV & PDF Tax / Expense Reports'
];
const rawProps = Array.isArray(parsed.valueProps) ? parsed.valueProps : [];
const valueProps = [0, 1, 2, 3].map(i => cleanAscii(rawProps[i], defaultProps[i]).slice(0, 48));

const instagramCaption = isCostcoRealStory
  ? `I bought items at Costco, scanned my receipt into Keeps, and got Email + Push Alerts when the prices dropped! Walked into Costco and got $55+ refunded straight back to my Visa ($43.56 + $16.34 receipts shown in video)!\n\nWhy Smart Shoppers Use Keeps:\n• 1-Tap AI Receipt & Warranty Scanner\n• 24/7 Auto Price Watch (Email + Push Alerts)\n• Return Window Countdown Reminders\n\nSearch "Keeps Receipt Scanner" on the App Store & Google Play or download here:\nApp Store: https://apps.apple.com/app/id6758263177\nGoogle Play: https://play.google.com/store/apps/details?id=com.anantaventures.keeps\n\n${flatHashtags.join(' ')}`
  : (parsed.instagramCaption || `${hook}\n\nWhy Smart Shoppers Use Keeps:\n• 1-Tap AI Receipt & Warranty Scanner\n• 24/7 Auto Price Watch (Checks Every 4 Hours)\n• Return Window Countdown Push Alerts\n\nSearch "Keeps Receipt Scanner" on the App Store & Google Play or download here:\nApp Store: https://apps.apple.com/app/id6758263177\nGoogle Play: https://play.google.com/store/apps/details?id=com.anantaventures.keeps\n\n${flatHashtags.join(' ')}`);

return [{
  json: {
    ...cfg,
    title,
    heroHeadline,
    heroSubhead,
    hook,
    mainContent,
    cta,
    segments,
    sceneLines,
    caseStudy,
    useRealCostcoReceipts: isCostcoRealStory,
    painPoints,
    valueProps,
    hashtags: flatHashtags,
    instagramCaption
  }
}];

const d = $('Extract Script Array').first().json;
const durInfo = $('Check Audio Length').first().json;
const audioUrl = $('GCS - Upload Audio').first().json.mediaLink;

const pexelsPool1 = [
  'https://videos.pexels.com/video-files/9474093/9474093-hd_720_1280_24fps.mp4',
  'https://videos.pexels.com/video-files/5632371/5632371-hd_720_1280_25fps.mp4',
  'https://videos.pexels.com/video-files/7679830/7679830-hd_720_1280_25fps.mp4'
];
const pexelsPool2 = [
  'https://videos.pexels.com/video-files/7308301/7308301-hd_720_1280_24fps.mp4',
  'https://videos.pexels.com/video-files/6115066/6115066-hd_720_1366_25fps.mp4',
  'https://videos.pexels.com/video-files/8060394/8060394-hd_720_1366_25fps.mp4'
];
const idx = Math.floor(Math.random() * pexelsPool1.length);

return [{
  json: {
    mode: 'keeps_commercial',
    styleKey: d.styleKey,
    styleBadge: d.styleBadge,
    heroHeadline: d.heroHeadline,
    caseStudy: d.caseStudy,
    useRealCostcoReceipts: Boolean(d.useRealCostcoReceipts || d.styleKey === 'COSTCO_REAL_REFUND_STORY' || (d.caseStudy && d.caseStudy.store === 'COSTCO')),
    videoDurations: durInfo.videoDurations || [6.0, 6.0, 6.0, 6.5, 6.0, 6.5],
    totalAudioDuration: durInfo.totalAudioDuration || 37.0,
    audio_url: audioUrl,
    pexels_1_url: pexelsPool1[idx],
    pexels_2_url: pexelsPool2[idx]
  }
}];

const item = $input.first();
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
// OpenAI tts-1-hd MP3 is 128kbps = 16,000 bytes/sec
const rawAudioSeconds = binaryBuffer.length / 16000;
const totalAudioDuration = Number(Math.max(30, rawAudioSeconds + 2.2).toFixed(2));

const scriptData = $('Extract Script Array').first().json;
const sceneLines = Array.isArray(scriptData.sceneLines) && scriptData.sceneLines.length === 6
  ? scriptData.sceneLines
  : ['Scene 1', 'Scene 2', 'Scene 3', 'Scene 4', 'Scene 5', 'Scene 6'];

const weights = sceneLines.map(line => {
  const words = String(line || '').trim().split(/\s+/).filter(Boolean).length;
  return Math.max(8, words);
});
const totalWeight = weights.reduce((a, b) => a + b, 0) || 60;

const videoDurations = weights.map(w => {
  const d = (w / totalWeight) * totalAudioDuration;
  return Number(Math.max(4.5, d).toFixed(2));
});
const sumFirst5 = videoDurations.slice(0, 5).reduce((a, b) => a + b, 0);
videoDurations[5] = Number(Math.max(5.0, totalAudioDuration - sumFirst5).toFixed(2));
const finalDuration = Number(videoDurations.reduce((a, b) => a + b, 0).toFixed(2));

return [{
  json: {
    ...item.json,
    fileName: `keeps_commercial_${Date.now()}.mp3`,
    audioSize: binaryBuffer.length,
    totalAudioDuration: finalDuration,
    videoDurations,
    totalVideos: 6,
    durationStatus: 'good',
    targetDuration: finalDuration
  },
  binary: item.binary
}];

const item = $input.first();
const scriptData = $('Extract Script Array').first().json;
const rawTitle = scriptData.title || item.json.title || 'Stores Owe You Price Drop Refunds';

const safe = rawTitle
  .replace(/[:]/g, ' ')
  .replace(/\r?\n|\r/g, ' ')
  .replace(/[^\p{L}\p{N}\p{P}\p{Sc}\p{Z}]/gu, '')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 52);

const finalTitle = `${safe} #KeepsApp #PriceMatch #MoneyTips #Shorts`;
const description = scriptData.instagramCaption || `${scriptData.hook || 'Stop leaving money behind on receipts!'}\n\nSearch "Keeps Receipt Scanner" on the App Store & Google Play or download free:\nApp Store: https://apps.apple.com/app/id6758263177\nGoogle Play: https://play.google.com/store/apps/details?id=com.anantaventures.keeps\n\n#receiptscanner #pricematch #savingmoney #shoppinghacks #shorts`;

return [{
  json: { title: finalTitle, description },
  binary: item.binary
}];
